#include "apps/penumbra/ui/theme.h"

#include <cstdarg>
#include <cstddef>
#include <cstdio>

namespace pen {
// Generated by pen-embed-binary from third_party/fonts (apps/penumbra/CMakeLists.txt).
extern const unsigned char* const kPlexSansRegular;
extern const size_t kPlexSansRegularSize;
extern const unsigned char* const kPlexSansMedium;
extern const size_t kPlexSansMediumSize;
extern const unsigned char* const kPlexSansSemiBold;
extern const size_t kPlexSansSemiBoldSize;
extern const unsigned char* const kPlexMonoRegular;
extern const size_t kPlexMonoRegularSize;
extern const unsigned char* const kPlexMonoMedium;
extern const size_t kPlexMonoMediumSize;
}  // namespace pen

namespace pen::ui {

namespace {

Fonts g_fonts;

ImFont* addFont(const unsigned char* data, size_t size, const char* name) {
  ImFontConfig cfg;
  cfg.FontDataOwnedByAtlas = false;  // static data in the binary
  std::snprintf(cfg.Name, sizeof(cfg.Name), "%s", name);
  return ImGui::GetIO().Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(data), static_cast<int>(size),
                                                     size::kBody, &cfg);
}

ImVec4 v4(ImU32 c) { return ImGui::ColorConvertU32ToFloat4(c); }

}  // namespace

Fonts applyTheme(float scale) {
  g_fonts.sans = addFont(kPlexSansRegular, kPlexSansRegularSize, "IBM Plex Sans");
  g_fonts.sans_medium = addFont(kPlexSansMedium, kPlexSansMediumSize, "IBM Plex Sans Medium");
  g_fonts.sans_semibold = addFont(kPlexSansSemiBold, kPlexSansSemiBoldSize, "IBM Plex Sans SemiBold");
  g_fonts.mono = addFont(kPlexMonoRegular, kPlexMonoRegularSize, "IBM Plex Mono");
  g_fonts.mono_medium = addFont(kPlexMonoMedium, kPlexMonoMediumSize, "IBM Plex Mono Medium");

  ImGuiStyle& s = ImGui::GetStyle();
  ImGui::StyleColorsDark(&s);
  s.WindowPadding = ImVec2(0, 0);
  s.WindowBorderSize = 0;
  s.WindowRounding = 0;
  s.ChildRounding = 12;
  s.ChildBorderSize = 1;
  s.FrameRounding = 8;
  s.FramePadding = ImVec2(12, 8);
  s.FrameBorderSize = 1;
  s.ItemSpacing = ImVec2(12, 10);
  s.PopupRounding = 8;
  s.GrabRounding = 6;
  s.ScrollbarRounding = 8;
  s.ScrollbarSize = 10;
  s.TabRounding = 8;
  s.Colors[ImGuiCol_WindowBg] = v4(color::kBackground);
  s.Colors[ImGuiCol_ChildBg] = v4(color::kPanel);
  s.Colors[ImGuiCol_PopupBg] = v4(color::kPanel);
  s.Colors[ImGuiCol_Border] = v4(color::kBorder);
  s.Colors[ImGuiCol_Text] = v4(color::kText);
  s.Colors[ImGuiCol_TextDisabled] = v4(color::kTextSecondary);
  s.Colors[ImGuiCol_FrameBg] = v4(color::kBackground);
  s.Colors[ImGuiCol_FrameBgHovered] = v4(color::kSelected);
  s.Colors[ImGuiCol_FrameBgActive] = v4(color::kSelected);
  s.Colors[ImGuiCol_Button] = ImVec4(0, 0, 0, 0);
  s.Colors[ImGuiCol_ButtonHovered] = v4(color::kSelected);
  s.Colors[ImGuiCol_ButtonActive] = v4(color::kBorder);
  s.Colors[ImGuiCol_Header] = v4(color::kSelected);
  s.Colors[ImGuiCol_HeaderHovered] = v4(color::kSelected);
  s.Colors[ImGuiCol_HeaderActive] = v4(color::kBorder);
  s.Colors[ImGuiCol_CheckMark] = v4(color::kAccent);
  s.Colors[ImGuiCol_SliderGrab] = v4(color::kAccent);
  s.Colors[ImGuiCol_SliderGrabActive] = v4(color::kAccentHover);
  s.Colors[ImGuiCol_PlotHistogram] = v4(color::kAccent);
  s.Colors[ImGuiCol_Separator] = v4(color::kBorder);
  s.Colors[ImGuiCol_ScrollbarBg] = ImVec4(0, 0, 0, 0);
  s.Colors[ImGuiCol_TableHeaderBg] = v4(color::kPanel);
  s.Colors[ImGuiCol_TableBorderStrong] = v4(color::kBorder);
  s.Colors[ImGuiCol_TableBorderLight] = v4(color::kBorder);
  s.Colors[ImGuiCol_NavCursor] = v4(color::kAccent);
  s.ScaleAllSizes(scale);
  s.FontScaleDpi = scale;
  return g_fonts;
}

const Fonts& fonts() { return g_fonts; }

void text(ImFont* font, float size, ImU32 col, const char* fmt, ...) {
  ImGui::PushFont(font, size);
  ImGui::PushStyleColor(ImGuiCol_Text, col);
  va_list args;
  va_start(args, fmt);
  ImGui::TextV(fmt, args);
  va_end(args);
  ImGui::PopStyleColor();
  ImGui::PopFont();
}

}  // namespace pen::ui
